/**
 * Soft magnetic materials.
 *
 * Anchor values (permeability, saturation, one loss point) come from published
 * grade data. Variants are then generated by the relationships that actually
 * govern them:
 *
 * - Lamination thickness: classical eddy-current loss goes with t², so a
 *   thinner gauge of the same grade loses proportionally less at frequency.
 * - Powder-core permeability: a family is one powder pressed to different
 *   distributed gaps. Higher permeability means less gap, so loss per volume
 *   rises and DC-bias capability falls, both roughly with permeability.
 * - Temperature grade: saturation falls as a material approaches its Curie
 *   point; each grade carries its own Curie temperature.
 */

import { KNEE_SHARP, KNEE_SOFT, type CoreMaterial } from "../material-types";

