const ferriteColor = (mur: number) => (mur > 3000 ? 0x33383f : mur > 1000 ? 0x2f3338 : 0x3a3f45);

function ferriteEntries(): CoreMaterial[] {
  return FERRITES.map(
    ([id, name, mur, bsat, alpha, beta, refF, refB, refPv, maxFreq, curie, tags]) => ({
      id: `ferrite-${id}`,
      name: `페라이트 ${name}`,
      family: "MnZn 페라이트",
      mur,
      bsat,
      density: 4850,
      alpha,
      beta,
      refFreq: refF,
      refB,
      refLoss: refPv,
      knee: KNEE_SHARP,
      maxFreq,
      maxTemp: Math.round(curie * 0.55),
      curie,
      cost: 0.6 + mur / 20000,
      color: ferriteColor(mur),
      tags: ["페라이트", "ferrite", name.toLowerCase(), ...tags.split(" ")],
      provenance: "제조사 등급 데이터 (투자율·포화·손실 1점)",
      note: `${tags.split(" ")[0]} 용도. 큐리 온도 ${curie}°C.`,
    }),
  );
}

function powderEntries(): CoreMaterial[] {
  const out: CoreMaterial[] = [];
  for (const family of POWDER_FAMILIES) {
    for (const perm of family.perms) {
      // Less distributed gap means more of the flux swings in the powder
      // itself, so volumetric loss scales with permeability.
      const lossScale = Math.pow(perm / family.refPerm, 1.15);
      out.push({
        id: `${family.id}-${perm}`,
        name: `${family.name} ${perm}µ`,
        family: family.name,
        mur: perm,
        bsat: family.bsat,
        density: family.density,
        alpha: family.alpha,
        beta: family.beta,
        refFreq: 100e3,
        refB: 0.1,
        refLoss: family.refPv * lossScale,
        knee: KNEE_SOFT,
        maxFreq: perm > 200 ? 200e3 : 1e6,
        maxTemp: family.maxTemp,
        curie: 500,
        cost: family.cost * (1 + perm / 600),
        color: family.color,
        tags: ["분말코어", "powder", family.id, `${perm}u`, ...family.tags.split(" ")],
        provenance: `${family.name} 계열, 기준 ${family.refPerm}µ의 손실을 투자율비 1.15승으로 환산`,
        note: family.note,
      });
    }
  }
  return out;
}

function steelEntries(): CoreMaterial[] {
  const out: CoreMaterial[] = [];
  for (const [id, name, mur, bsat, refLossWkg, refThickness, oriented, tags] of STEEL_GRADES) {
    for (const thickness of STEEL_THICKNESS) {
      // Grain-oriented steel is not rolled thick; skip the combinations that
      // do not exist rather than inventing them.
      if (oriented && thickness > 0.35) continue;
      if (!oriented && thickness < 0.23) continue;
      // Classical eddy-current loss scales with thickness squared.
      const scale = Math.pow(thickness / refThickness, 2);
      const hysteresisShare = 0.55;
      const lossWkg = refLossWkg * (hysteresisShare + (1 - hysteresisShare) * scale);
      out.push({
        id: `steel-${id}-${String(thickness).replace(".", "")}`,
        name: `${oriented ? "" : "규소강판 "}${name} ${thickness}mm`,
        family: oriented ? "방향성 규소강" : "무방향성 규소강",
        mur,
        bsat,
        density: 7650,
        alpha: 1.6,
        beta: 2.0,
        refFreq: 60,
        refB: 1.5,
        refLoss: lossWkg * 7650,
        knee: KNEE_SHARP,
        maxFreq: Math.round(400 * Math.pow(0.35 / thickness, 1.5)),
        maxTemp: 155,
        curie: 745,
        cost: (oriented ? 0.5 : 0.25) * Math.pow(0.35 / thickness, 0.5),
        color: oriented ? 0x9aa3ad : 0x8a9099,
        tags: ["규소강", "steel", "적층", name.toLowerCase(), `${thickness}mm`, ...tags.split(" ")],
        provenance: `${name} 기준 두께 ${refThickness}mm의 비손실을 두께 제곱으로 환산 (와전류 성분만)`,
        note: `${thickness}mm 적층. 60Hz 1.5T에서 ${lossWkg.toFixed(2)} W/kg.`,
      });
    }
  }
  return out;
}

function specialEntries(): CoreMaterial[] {
  return SPECIALS.map(
    ([id, name, family, mur, bsat, density, refF, refB, refPv, maxFreq, curie, cost, knee, color, tags, note]) => ({
      id,
      name,
      family,
      mur,
      bsat,
      density,
      alpha: family === "아몰퍼스" || family === "나노결정" ? 1.5 : 1.6,
      beta: family === "아몰퍼스" ? 1.8 : 2.0,
      refFreq: refF,
      refB,
      refLoss: refPv,
      knee,
      maxFreq,
      maxTemp: Math.min(200, Math.round(curie * 0.4)),
      curie,
      cost,
      color,
      tags: ["특수", ...tags.split(" ")],
      provenance: "재료 등급 공개 데이터",
      note,
    }),
  );
}

export const CORE_MATERIALS: CoreMaterial[] = [
  ...specialEntries(),
  ...ferriteEntries(),
  ...powderEntries(),
  ...steelEntries(),
];
